};

// Select `from`, press on the drag dot nearest `to`, move in steps to `to`'s center, release.
export const dragRelation = async ({ client, json }, from, to) => {
  await client.evaluate(`window.__dgEd.select(${json(from)}); return true;`);
  await sleep(300);
  const sel = await client.evaluate(`return window.__dgEd.getSelectedShapeIds();`);
  if (sel.length !== 1 || sel[0] !== from) throw new Error(`expected ${from} selected, got ${sel}`);
  const pts = await client.evaluate(`
    const ed = window.__dgEd;
    const b = ed.getShapePageBounds(${json(to)});
    const target = ed.pageToScreen({ x: b.midX, y: b.midY });
    const dots = [...ed.getContainer().querySelectorAll(".cursor-crosshair")].map((d) => {
      const r = d.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    });
    dots.sort((a, c) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(c.x - target.x, c.y - target.y));
    return { start: dots[0], target, dotCount: dots.length };`);
  if (!pts.start) throw new Error("no drag handle dots rendered");
  const { start, target } = pts;
  await mouse(client, "mouseMoved", start.x, start.y, { button: "none" });
  await mouse(client, "mousePressed", start.x, start.y, { buttons: 1 });
  for (let i = 1; i <= 12; i++) {
    const t = i / 12;
    await mouse(client, "mouseMoved", start.x + (target.x - start.x) * t, start.y + (target.y - start.y) * t, { buttons: 1 });
    await sleep(20);
  }
  await mouse(client, "mouseReleased", target.x, target.y);
  await sleep(400);
  return pts;
};

