// ENG-2328: relation type menu draws above tldraw's style panel and is centred on the arrow midpoint.
import { prepare, dragRelation } from "./base2256.mjs";

const C = "shape:verify-bqu6_";
const E = "shape:verify-4dCoS";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
// Default camera puts Evidence -> Claim near the right edge, under the style panel.
const EDGE_CAM = { x: 150, y: 150, z: 0.8 };

const mouse = (client, type, x, y, extra = {}) =>
  client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });
const clickAt = async (client, { x, y }) => {
  await mouse(client, "mouseMoved", x, y, { button: "none" });
  await mouse(client, "mousePressed", x, y, { buttons: 1 });
  await mouse(client, "mouseReleased", x, y);
  await sleep(250);
};

// Root found structurally (header span -> header row -> menu -> root), not by class.
const ROOT = `(() => {
  const h = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
  return h?.parentElement?.parentElement?.parentElement ?? null;
})()`;

const observe = ({ client }) =>
  client.evaluate(`
    const ed = window.__dgEd;
    const root = ${ROOT};
    const R = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return [r.left, r.top, r.right, r.bottom].map(Math.round); };
    const hits = (el) => { if (!el) return false; const r = el.getBoundingClientRect(); return el.contains(document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2)); };
    const plus = root?.querySelector('[aria-label="Add relation type"]');
    const flyout = root?.children[1] ?? null;
    const arrows = ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation");
    let centre = null;
    if (root) {
      const r = root.getBoundingClientRect();
      const o = root.offsetParent.getBoundingClientRect();
      const ax = o.left + parseFloat(root.style.left), ay = o.top + parseFloat(root.style.top);
      const b = arrows[0] && ed.getShapePageBounds(arrows[0].id);
      const bc = b && ed.pageToScreen({ x: b.midX, y: b.midY });
      centre = { dx: Math.round(r.left + r.width / 2 - ax), dy: Math.round(r.top + r.height / 2 - ay),
        boundsDist: bc ? Math.round(Math.hypot(ax - bc.x, ay - bc.y)) : null,
        zIndex: getComputedStyle(root).zIndex, transform: getComputedStyle(root).transform };
    }
    const c = ed.getContainer().getBoundingClientRect();
    const inside = (el) => { const r = el.getBoundingClientRect(); return r.left >= c.left && r.right <= c.right && r.top >= c.top && r.bottom <= c.bottom; };
    return {
      menuOpen: !!root, centre, root: R(root), panel: R(document.querySelector(".tlui-style-panel")),
      plus: plus ? { onTop: hits(plus), expanded: plus.getAttribute("aria-expanded") } : null,
      flyout: flyout ? { rect: R(flyout), inCanvas: inside(flyout), buttonsOnTop: [...flyout.querySelectorAll("button")].map(hits) } : null,
      arrowCount: arrows.length,
    };`);

export default [
  {
    name: "Plus button above style panel near right edge",
    input: "Evidence to Claim at the default camera (menu overlaps style panel); hit-test + centre",
    expected: "elementFromPoint at + centre is the + button; menu z-index 301",
    run: async (ctx) => {
      await prepare(ctx, EDGE_CAM);
      await dragRelation(ctx, E, C);
      return observe(ctx);
    },
    expect: (o) => {
      const overlaps = o.panel && o.root && o.root[2] > o.panel[0] && o.root[0] < o.panel[2];
      return {
        pass: o.menuOpen && overlaps && o.plus?.onTop && o.centre.zIndex === "301",
        actual: `+onTop=${o.plus?.onTop} z=${o.centre?.zIndex} menu=${o.root} stylePanel=${o.panel} overlap=${overlaps}`,
      };
    },
  },
  {
    name: "Plus click opens flyout fully visible",
    input: "same; real click on +",
    expected: "flyout open, inside the canvas, every flyout button is topmost at its centre",
    run: async (ctx) => {
      await prepare(ctx, EDGE_CAM);
      await dragRelation(ctx, E, C);
      const p = await ctx.client.evaluate(`const b = ${ROOT}?.querySelector('[aria-label="Add relation type"]'); const r = b.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
      await clickAt(ctx.client, p);
      return observe(ctx);
    },
    expect: (o) => ({
      pass: o.plus?.expanded === "true" && o.flyout?.inCanvas && o.flyout.buttonsOnTop.length === 2 && o.flyout.buttonsOnTop.every(Boolean),
      actual: `expanded=${o.plus?.expanded} flyout=${o.flyout?.rect} inCanvas=${o.flyout?.inCanvas} buttonsOnTop=${o.flyout?.buttonsOnTop}`,
    }),
  },
  {
    name: "Menu centred on arrow midpoint",
    input: "Evidence to Claim; compare menu rect centre with its anchor (arrow midpoint in viewport)",
    expected: "centre within 1px of anchor; anchor near the arrow's bounds centre",
    run: async (ctx) => {
      await prepare(ctx, { x: -150, y: 150, z: 0.8 });
      await dragRelation(ctx, E, C);
      return observe(ctx);
    },
    expect: (o) => ({
      pass: o.menuOpen && Math.abs(o.centre.dx) <= 1 && Math.abs(o.centre.dy) <= 1 && o.centre.boundsDist <= 10,
      actual: `dx=${o.centre?.dx} dy=${o.centre?.dy} anchorToBoundsCentre=${o.centre?.boundsDist}px transform=${o.centre?.transform}`,
    }),
  },
  {
    name: "Click outside dismisses menu and deletes arrow",
    input: "Evidence to Claim; click empty canvas",
    expected: "menu gone, pending arrow deleted",
    run: async (ctx) => {
      await prepare(ctx, EDGE_CAM);
      await dragRelation(ctx, E, C);
      const before = await observe(ctx);
      const p = await ctx.client.evaluate(`const s = window.__dgEd.pageToScreen({ x: 150, y: 450 }); return { x: s.x, y: s.y };`);
      await clickAt(ctx.client, p);
      await sleep(300);
      return { before, after: await observe(ctx) };
    },
    expect: ({ before, after }) => ({
      pass: before.menuOpen && before.arrowCount === 1 && !after.menuOpen && after.arrowCount === 0,
      actual: `before menu=${before.menuOpen} arrows=${before.arrowCount}; after menu=${after.menuOpen} arrows=${after.arrowCount}`,
    }),
  },
  {
    name: "Escape dismisses menu and deletes arrow",
    input: "Evidence to Claim; press Escape",
    expected: "menu gone, pending arrow deleted",
    run: async (ctx) => {
      await prepare(ctx, EDGE_CAM);
      await dragRelation(ctx, E, C);
      const before = await observe(ctx);
      await ctx.client.pressEscape();
      await sleep(300);
      return { before, after: await observe(ctx) };
    },
    expect: ({ before, after }) => ({
      pass: before.menuOpen && before.arrowCount === 1 && !after.menuOpen && after.arrowCount === 0,
      actual: `before menu=${before.menuOpen} arrows=${before.arrowCount}; after menu=${after.menuOpen} arrows=${after.arrowCount}`,
    }),
  },
  {
    name: "Style panel, toolbar and main menu work with menu closed",
    input: "no relation menu; select Claim; hit-test style panel; click toolbar draw tool; open tldraw main menu",
    expected: "style panel topmost; tool switches to draw; main menu opens and is topmost",
    run: async (ctx) => {
      await prepare(ctx, EDGE_CAM);
      const { client, json } = ctx;
      await client.evaluate(`window.__dgEd.select(${json(C)}); return true;`);
      await sleep(300);
      const panel = await client.evaluate(`const p = document.querySelector(".tlui-style-panel"); if (!p) return null; const r = p.getBoundingClientRect(); return p.contains(document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2));`);
      const tool = await client.evaluate(`const b = document.querySelector('[data-testid="tools.draw"]'); if (!b) return null; const r = b.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
      if (tool) await clickAt(client, tool);
      const toolId = await client.evaluate(`return window.__dgEd.getCurrentToolId();`);
      await client.evaluate(`window.__dgEd.setCurrentTool("select"); return true;`);
      const mm = await client.evaluate(`const b = document.querySelector('[data-testid="main-menu.button"]'); if (!b) return null; const r = b.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
      let menu = null;
      if (mm) {
        await clickAt(client, mm);
        await sleep(300);
        menu = await client.evaluate(`const m = document.querySelector(".tlui-menu"); if (!m) return { open: false }; const r = m.getBoundingClientRect(); return { open: true, onTop: m.contains(document.elementFromPoint(r.left + r.width / 2, r.top + 10)) };`);
        await client.pressEscape();
      }
      return { panel, toolFound: !!tool, toolId, mainMenuFound: !!mm, menu };
    },
    expect: (o) => ({
      pass: o.panel === true && o.toolId === "draw" && (!o.mainMenuFound || (o.menu?.open && o.menu.onTop)),
      actual: `stylePanelOnTop=${o.panel} toolbarDraw=${o.toolFound}->${o.toolId} mainMenu=${o.mainMenuFound} open=${o.menu?.open} onTop=${o.menu?.onTop}`,
    }),
  },
];

